//! Requirements of the modelled system (R10).
//!
//! Each requirement is a named trait generated by `model_core::requirement!`;
//! the `/// REQ-NNN:` definition lines are written literally at the
//! invocation sites so trace.sh sees them (F-021). Requirements are used
//! **only as bounds** in process signatures (F-019) — see
//! `resources::processes::drill_plate`.
//!
//! **Design note (probe):** the requirement sentence "drilling requires a
//! certified operator *and* a fitted guard" spans two participants. A single
//! R10 trait cannot bound two process parameters at once, so the sentence
//! decomposes into one requirement trait per constrained parameter — REQ-001
//! on the operator, REQ-002 on the guard — both bound on the same
//! `drill_plate` line. trace.sh then reports the one process under both IDs,
//! which reads correctly in the traceability table.
//!
//! **Error-message probe:** REQ-001 carries its own
//! `#[diagnostic::on_unimplemented]` (passed through `requirement!`'s meta
//! slot); REQ-002 does not. The compile-fail cases compare the two shapes —
//! with the attribute the top-line message is requirement-phrased; without
//! it, rustc falls back to the generic "the trait `Req…` is not implemented"
//! plus the supertrait's message further down.

use crate::qualifications::{CertifiedDriller, Fitted};

model_core::requirement! {
    /// REQ-001: Drilling must be performed by an operator certified for drilling.
    #[diagnostic::on_unimplemented(message = "this person may not drill: `{Self}` is not a certified drilling operator (REQ-001)", label = "REQ-001: drilling requires a certified drilling operator", note = "qualifications are granted at the boundary (R12): `certify::<DrillingCert>(person)` wraps a `Person` into a certified `Operator`")]
    pub trait Req001CertifiedDrillingOperator: (CertifiedDriller);
    assert = assert_req001;
}

model_core::requirement! {
    /// REQ-002: Drilling must happen behind a machine guard fitted to the drill.
    pub trait Req002FittedDrillGuard: (Fitted);
    assert = assert_req002;
}
